begin;
create extension if not exists pgtap with schema extensions;
grant usage on schema extensions to authenticated;
set search_path=public,extensions;
select extensions.no_plan();
insert into auth.users(id,raw_user_meta_data) values
 ('aa000000-0000-4000-8000-000000000001','{"display_name":"Live learner"}'),
 ('aa000000-0000-4000-8000-000000000002','{"display_name":"Other learner"}'),
 ('aa000000-0000-4000-8000-000000000003','{"display_name":"Editor"}');
insert into private.user_roles(user_id,role) values('aa000000-0000-4000-8000-000000000003','admin');
insert into public.rooms(id,slug,name,kind,capacity,status) values('aa100000-0000-4000-8000-000000000001','live-test','Test study circle','study',2,'published');
create temporary table flow_state(run_id uuid,response jsonb);
grant select,insert,update on flow_state to authenticated;
set local role authenticated;
select set_config('request.jwt.claim.sub','aa000000-0000-4000-8000-000000000001',true);
insert into flow_state(response) select public.platform_action('start_practice','{"lessonId":"22000000-0000-4000-8000-000000000001"}');
update flow_state set run_id=(response->>'id')::uuid;
select extensions.is(jsonb_array_length((select response->'questions' from flow_state)),2,'Live lesson snapshots its published questions');
select extensions.ok(not exists(select 1 from flow_state,jsonb_array_elements(response->'questions') q where q ? 'solution' or q ? 'explanation'),'Starting a lesson never exposes answer keys');
select extensions.throws_ok($$select public.platform_action('finish_practice',jsonb_build_object('runId',(select run_id from flow_state)))$$,'P0001','Answer every exercise before finishing','Incomplete lessons cannot earn rewards');
select extensions.is(public.platform_action('answer',jsonb_build_object('runId',(select run_id from flow_state),'exerciseId','23000000-0000-4000-8000-000000000001','answer','a'))->>'correct','true','Choice answers are graded using private solutions');
select extensions.is(public.platform_action('answer',jsonb_build_object('runId',(select run_id from flow_state),'exerciseId','23000000-0000-4000-8000-000000000001','answer','wrong'))->>'correct','true','Submitted answers are immutable and idempotent');
select set_config('request.jwt.claim.sub','aa000000-0000-4000-8000-000000000002',true);
select extensions.throws_ok($$select public.platform_action('answer',jsonb_build_object('runId',(select run_id from flow_state),'exerciseId','23000000-0000-4000-8000-000000000002','answer','こんにちは'))$$,'42501','Practice session not found','Another user cannot submit answers to your session');
select set_config('request.jwt.claim.sub','aa000000-0000-4000-8000-000000000001',true);
select extensions.is(public.platform_action('answer',jsonb_build_object('runId',(select run_id from flow_state),'exerciseId','23000000-0000-4000-8000-000000000002','answer','こんにちは'))->>'correct','true','Typing supports the original seed answer format');
update flow_state set response=public.platform_action('finish_practice',jsonb_build_object('runId',run_id));
select extensions.is((select (response->>'accuracy')::numeric from flow_state),100::numeric,'Completed lesson accuracy is calculated on the server');
select extensions.is((select total_xp from public.account_progress),100::bigint,'Lesson, first achievement and daily quest award the correct XP');
select extensions.is((select current_streak from public.account_progress),1,'First activity starts an actual streak');
select extensions.lives_ok($$select public.platform_action('finish_practice',jsonb_build_object('runId',(select run_id from flow_state)))$$,'Completing the same run again is idempotent');
select extensions.is((select total_xp from public.account_progress),100::bigint,'Duplicate completion cannot mint XP');
select extensions.is((select count(*) from public.lesson_progress where completed_at is not null),1::bigint,'Successful completion persists lesson progress');
select extensions.is((select count(*) from public.user_achievements where earned_at is not null),1::bigint,'Achievements unlock from trusted activity');
select extensions.throws_ok($$select public.platform_action('admin_users','{}')$$,'42501','Administrator access required','Learners cannot enumerate private users');
select extensions.throws_ok($$select public.platform_action('room_feed','{"roomId":"aa100000-0000-4000-8000-000000000001"}')$$,'42501','Join this room first','Chat requires room membership');
select extensions.lives_ok($$select public.platform_action('join_room','{"roomId":"aa100000-0000-4000-8000-000000000001"}')$$,'Eligible user joins an actual room');
select extensions.is(jsonb_array_length(public.platform_action('send_message','{"roomId":"aa100000-0000-4000-8000-000000000001","body":"Hello, everyone!"}')),1,'Chat message persists and appears in the room feed');
select extensions.throws_ok($$select public.platform_action('send_message','{"roomId":"aa100000-0000-4000-8000-000000000001","body":"Another message"}')$$,'P0001','Please wait a moment before sending again','Room sending rate limit is enforced');
select extensions.lives_ok($$select public.platform_action('save_avatar','{"schemaVersion":1,"modelFamily":"humanoid-v1","selections":[{"slot":"body","assetKey":"body.traveler","assetVersion":1,"options":{"tint":"#deb99e"}},{"slot":"hair","assetKey":"hair.soft-bob","assetVersion":1,"options":{"tint":"#343735"}},{"slot":"top","assetKey":"top.academy-jacket","assetVersion":1,"options":{"tint":"#747e69"}}]}')$$,'Avatar saves atomically with validated owned/free equipment');
select extensions.is((select count(*) from public.avatar_equipment),3::bigint,'Saved avatar has three persistent equipment selections');
select extensions.throws_ok($$select public.platform_action('save_avatar','{"schemaVersion":1,"modelFamily":"humanoid-v1","selections":[{"slot":"accessory","assetKey":"accessory.explorer-pin","assetVersion":1,"options":{}}]}')$$,'42501','An item is unavailable, incompatible, or not unlocked','Avatar RPC cannot grant locked cosmetics');
select extensions.lives_ok($$select public.platform_action('generate_material','{"templateId":"70000000-0000-4000-8000-000000000001"}')$$,'A real workbook is generated from published exercises');
select extensions.is((select count(*) from public.generated_materials where status='ready'),1::bigint,'Workbook is persisted to its owner');
select extensions.is(jsonb_array_length(public.platform_action('leaderboard','{"period":"all"}')),0,'Private learners do not appear in rankings');
update public.profiles set is_public=true where id=auth.uid();
update public.user_settings set leaderboard_opt_in=true where user_id=auth.uid();
select extensions.is(jsonb_array_length(public.platform_action('leaderboard','{"period":"all"}')),1,'Public opted-in learner appears in real rankings');
select set_config('request.jwt.claim.sub','aa000000-0000-4000-8000-000000000002',true);
select extensions.is((select count(*) from public.generated_materials),0::bigint,'Generated workbook stays private to its owner');
select extensions.is((select count(*) from public.lesson_attempts),0::bigint,'Learning attempts stay private to their owner');
select set_config('request.jwt.claim.sub','aa000000-0000-4000-8000-000000000003',true);
select extensions.lives_ok($$select public.platform_action('save_exercise','{"exercise":{"lesson_id":"22000000-0000-4000-8000-000000000001","position":99,"type":"typing","prompt":"Translate hello","payload":{},"status":"draft"},"solution":{"answers":["hello"]},"explanation":"Hello is a greeting."}')$$,'Administrators save exercise and private answer key atomically');
select extensions.is(jsonb_array_length(public.platform_action('admin_users','{}')),3,'Administrators can inspect actual user records');
select extensions.finish();
rollback;
